; Room drawing: colours, run-length map decoder and per-room state reset
; $09bc-$0b49

; Draw the current room and reset the per-room state. Called by change_room, start_new_game and
; start_attract_demo. Screen and sprites are off while it draws.
; 1. Clears status row 0, fills colour RAM rows 3-24 with room_colour_fill[room], clears the fireball
;    sprites and silences the sound effects.
; 2. Room 11 when room_lanterns_left of rooms 12, 14 and 16 are all 0: goes to room 13 instead
;    (place_bruce_at_room_start with X = 13).
; 3. First visit of the room by the current player (room_unvisited[room*2 + current_player] = 1): clears the
;    flag and adds 2000 points.
; 4. Clears actor_move_queue (the move history of the actors, $4F57-$4FDA), room_time and
;    anim_chars_direction; anim_chars_speed_step = 7.
; 5. room_no_enemy_flag = room_no_enemies[room] (nonzero also clears enemy_follow_x). Loads the spawn timers
;    from ninja_room_delay / yamo_room_delay (3 for both when game_loop_count is nonzero, Yamo 8 when player 2
;    controls him).
; 6. Resets Bruce's actor_contact, actor_timer, actor_state and actor_step_delay and the burst_trap_timer
;    slots, copies the 20-byte block of room_aux_ptr to room_band_colours and sets room_vmcsb:
;    charset_rooms_0_9 for rooms 0-9, charset_wizard for room 18, charset_rooms_10_19 for the others.
; 7. Decodes the run-length room map (room_map_ptr_lo/hi) into screen rows 3-24.
; 8. setup_room_lanterns_and_init (lanterns, room init), screen and sprites 0-4 on, then tail-jumps to
;    run_room_frame_handler (the room's frame handler runs once and returns to the caller).
; Map format: a stream of codes. $80 ends the map. $81-$FF: (code AND $7F) literal tile bytes follow.
; $01-$7F: one tile byte follows, repeated code times. A tile byte draws one double-height cell: bits 0-6
; = character c (upper row c, lower row c+128), bit 7 = colour RAM $F8 (multicolour, colour 0) for the cell
; instead of the room colour. Cells fill 40 columns, then the next double row.
draw_room
        lda SCROLY                      ; screen off
        and #$ef
        sta SCROLY                      ; screen off; also copies raster bit 8 into the compare line (see $0B33)
        lda SPENA                       ; remember sprites 0-4 enable bits
        and #$1f
        sta saved_sprite_enable
        lda #$00
        sta SPENA                       ; $d015: sprites 
        ldx #$27
        lda #$20
draw_room_clear_top_row
        sta game_screen,x
        dex
        bpl draw_room_clear_top_row
        ldx room
        lda room_colour_fill,x          ; room colour (multicolour flag + colour)
        ldx #$00
draw_room_fill_colours
        sta $d800+3*40,x                ; colour RAM rows 3-24
        sta $d900,x
        sta $da00,x
        sta $db00,x
        inx
        bne draw_room_fill_colours
        jsr clear_fireball_sprites      ; clear the fireball sprite rows
        jsr stop_all_sounds             ; silence the sound effects
; Room 11: when rooms 12, 14 and 16 have no lanterns left, go to room 13 instead.
        lda room
        cmp #$0b
        bne draw_room_first_visit_check
        lda room_lanterns_left+$c       ; lanterns left in rooms 12, 14 and 16
        ora room_lanterns_left+$e
        ora room_lanterns_left+$10
        bne draw_room_first_visit_check
; not executed $0a04-$0a0d
        lda saved_sprite_enable
        sta SPENA
        ldx #$0d
        jmp place_bruce_at_room_start   ; enter room X = 13 (place_bruce_at_room_start draws it)
draw_room_first_visit_check
        lda room
        asl
        adc current_player              ; + current player: room*2 + player
        tax
        lda room_unvisited,x            ; first-visit flag of this room and player
        beq draw_room_reset_state
        lsr room_unvisited,x
        lda #$07                        ; add $07 at score byte 1 (1792 points) ...
        ldx #$01
        jsr add_score
        lda #$d0                        ; ... and $D0 at byte 2 (208): 2000 points
        ldx #$02
        jsr add_score
draw_room_reset_state
        lda #$00
        ldy #$83                        ; 132 bytes
draw_room_clear_object_state
        sta actor_move_queue,y          ; clear actor_move_queue: 11 records x 4 directions x 3 actors ($4F57-$4FDA)
        dey
        bpl draw_room_clear_object_state
        sta room_time                   ; room_time = 0
        sta room_time+1
        sta anim_chars_direction
        lda #$07                        ; restart the speed curve of the animated chars
        sta anim_chars_speed_step
        ldx room
        lda room_no_enemies,x           ; nonzero: no Yamo or Ninja in this room
        sta room_no_enemy_flag
        beq draw_room_load_spawn_timers
        lda #$00                        ; no carried-over enemy positions
        sta enemy_follow_x
        sta enemy_follow_x+1
draw_room_load_spawn_timers
        lda ninja_room_delay,x          ; Ninja spawn timer
        sta ninja_spawn_timer
        lda yamo_room_delay,x           ; Yamo spawn timer
        sta yamo_spawn_timer
        lda game_loop_count             ; completed games: both enemies come at once
        beq draw_room_check_two_player_yamo
        lda #$03
        sta ninja_spawn_timer
        sta yamo_spawn_timer
draw_room_check_two_player_yamo
        lda option_yamo_player2         ; player 2 controls Yamo: Yamo comes after 8 passes
        beq draw_room_reset_bruce
        lda #$08
        sta yamo_spawn_timer
; Reset Bruce (actor 0): actor_contact = 1 (floor), actor_timer = 4, actor_state = 0, actor_step_delay = 0;
; free the three burst trap slots (burst_trap_timer).
draw_room_reset_bruce
        lda #$01
        sta actor_contact
        lda #$04
        sta actor_timer
        lda #$00
        sta burst_trap_timer
        sta burst_trap_timer+1
        sta burst_trap_timer+2
        sta actor_state
        sta actor_step_delay
; Copy the 20-byte block of the room (room_aux_ptr[room]) to room_band_colours ($0153-$0166).
; irq_game_bottom rewrites the first 12 bytes every frame from room_palette_ptr; nothing reads the last 8.
        lda room
        asl
        tax
        lda room_aux_ptr,x
        sta data_ptr
        lda room_aux_ptr+1,x
        sta data_ptr+1
        ldy #$13
draw_room_copy_room_record
        lda (data_ptr),y
        sta room_band_colours,y
        dey
        bpl draw_room_copy_room_record
        lda #$38                        ; room_vmcsb $38: charset_rooms_0_9 (rooms 0-9)
        ldx room
        cpx #$0a
        bcc draw_room_set_charset
        cpx #$12
        beq draw_room_wizard_charset
        lda #$3a                        ; $3A: charset_rooms_10_19 (rooms 10-17 and 19)
        bne draw_room_set_charset
draw_room_wizard_charset
        lda #$3c                        ; $3C: charset_wizard (room 18)
draw_room_set_charset
        sta room_vmcsb
; Decode the room map. data_ptr = map, row_ptr_top / row_ptr_bottom = screen rows 3 / 4, colour_ptr_top /
; colour_ptr_bottom = colour RAM rows 3 / 4. Y stays 0; X counts the cells of a run.
        lda room_map_ptr_lo,x           ; room map pointer, low/high split table
        sta data_ptr
        lda room_map_ptr_hi,x
        sta data_ptr+1
        lda #<(game_screen+3*40)        ; screen row 3 (upper half of the cells) ...
        sta row_ptr_top
        sta colour_ptr_top              ; ... and colour RAM row 3 have the same low byte
        lda #<(game_screen+4*40)        ; screen row 4 (lower half) and colour RAM row 4
        sta row_ptr_bottom
        sta colour_ptr_bottom
        lda #>(game_screen+3*40)
        sta row_ptr_top+1
        sta row_ptr_bottom+1
        lda #$d8                        ; colour RAM $D878 / $D8A0
        sta colour_ptr_top+1
        sta colour_ptr_bottom+1
        lda #$27                        ; 40 columns (count - 1) for room_draw_step_cell
        sta column_counter
        ldy #$00
draw_room_next_code
        lda (data_ptr),y
        bpl draw_room_repeat_run        ; $01-$7F: repeat run
        and #$7f                        ; $80: end of map; $81-$FF: literal run
        beq draw_room_done
        tax
        jsr inc_data_ptr                ; skip the count byte
draw_room_literal_loop
        lda (data_ptr),y
        bpl draw_room_store_literal     ; bit 7: black cell
        jsr map_tile_set_black
draw_room_store_literal
        sta (row_ptr_top),y             ; top half: character c
        ora #$80
        sta (row_ptr_bottom),y          ; bottom half: character c+128
        jsr inc_row_ptr_top             ; next top cell
        jsr inc_data_ptr                ; next map byte
        jsr inc_row_ptr_bottom          ; next bottom cell
        jsr inc_colour_ptr_top
        jsr inc_colour_ptr_bottom
        jsr room_draw_step_cell         ; count columns; after 40 skip to the next double row
        dex
        bne draw_room_literal_loop
        beq draw_room_next_code         ; always taken
draw_room_repeat_run
        tax
        jsr inc_data_ptr                ; skip the count byte
draw_room_repeat_loop
        lda (data_ptr),y
        bpl draw_room_store_repeat
        jsr map_tile_set_black
draw_room_store_repeat
        sta (row_ptr_top),y
        ora #$80
        sta (row_ptr_bottom),y
        jsr inc_row_ptr_top
        jsr inc_row_ptr_bottom
        jsr inc_colour_ptr_top
        jsr inc_colour_ptr_bottom
        jsr room_draw_step_cell
        dex
        bne draw_room_repeat_loop
        jsr inc_data_ptr                ; skip the repeated tile byte
        jmp draw_room_next_code
draw_room_done
        jsr setup_room_lanterns_and_init ; draw the lanterns of the room
; Freeze: bit 7 of a SCROLY read is the current raster line bit 8, and the write puts it into bit 8 of the
; raster compare line. change_room runs draw_room under SEI. When the screen-off write ($09C1) and this screen-on
; write both come on raster lines 256-311, the compare line stays above 311 (for example 256 + 64 = 320). The
; raster IRQ then never fires again, frame_countdown stays 3, and main_loop waits for ever. When the screen-off
; write comes before line 256, the compare line still matches during the draw, and the IRQ runs after the CLI.
        lda SCROLY                      ; screen on
        ora #$10
        sta SCROLY
        lda saved_sprite_enable
        sta SPENA
        jmp run_room_frame_handler      ; the room's frame handler runs once
; Increment the 16-bit pointer row_ptr_top. Same code as inc_row_ptr_top. Only caller: swap_room_lanterns (not
; executed).
inc_pointer_04_copy
        inc row_ptr_top
        bne inc_pointer_04_copy_done
; not executed $0b47-$0b48
        inc row_ptr_top+1
inc_pointer_04_copy_done
        rts
